SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."name" AS "name", "_root.ar.root.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 2000 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("articles" ), '[]' ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.base"."id" AS "id", "_root.ar.root.articles.base"."title" AS "title", "_root.ar.root.articles.ar.articles.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "articles" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))     ) AS "_root.ar.root.articles.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.ar.articles.comments.base"."body" AS "body"       ) AS "_e"      ) ) AS "comments" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.ar.root.articles.base"."id") = ("article_id"))     ) AS "_root.ar.root.articles.ar.articles.comments.base"      ) AS "_root.ar.root.articles.ar.articles.comments"      ) AS "_root.ar.root.articles.ar.articles.comments" ON ('true')      ) AS "_root.ar.root.articles"      ) AS "_root.ar.root.articles" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
